#!/bin/bash

# ============================================================
# check_links.sh
# Reads the JSON generated by extract_links.sh and verifies
# whether each link responds correctly or returns an error.
#
# Usage: ./check_links.sh <links.json> [output.json] [options]
#
# Options:
#   --timeout  N   Seconds before a request times out (default: 10)
#   --retries  N   Retry attempts on network failure   (default: 2)
#   --parallel N   Number of simultaneous requests     (default: 5)
# ============================================================

set -euo pipefail

# --- Colors (disabled in CI environments for clean logs) ---
# GitHub Actions automatically sets $CI=true, which disables ANSI codes
if [[ -n "${CI:-}" ]]; then
  RED=''; GREEN=''; YELLOW=''; CYAN=''; BOLD=''; NC=''
else
  RED='\033[0;31m'
  GREEN='\033[0;32m'
  YELLOW='\033[1;33m'
  CYAN='\033[0;36m'
  BOLD='\033[1m'
  NC='\033[0m' # No Color
fi

# --- Default arguments ---
INPUT_FILE="${1:-links_output.json}"
OUTPUT_FILE="${2:-links_checked.json}"
TIMEOUT=10
RETRIES=2
PARALLEL=5

# --- Parse extra options ---
shift 2 2>/dev/null || true
while [[ $# -gt 0 ]]; do
  case "$1" in
    --timeout)  TIMEOUT="$2";  shift 2 ;;
    --retries)  RETRIES="$2";  shift 2 ;;
    --parallel) PARALLEL="$2"; shift 2 ;;
    *) echo "⚠️  Unknown option: $1" >&2; shift ;;
  esac
done

# --- Validations ---
if [[ ! -f "$INPUT_FILE" ]]; then
  echo -e "${RED}❌ Error: File '$INPUT_FILE' does not exist.${NC}" >&2
  exit 1
fi

command -v curl >/dev/null 2>&1 || { echo -e "${RED}❌ 'curl' is required.${NC}" >&2; exit 1; }
command -v grep >/dev/null 2>&1 || { echo -e "${RED}❌ 'grep' is required.${NC}" >&2; exit 1; }
command -v sed  >/dev/null 2>&1 || { echo -e "${RED}❌ 'sed' is required.${NC}" >&2; exit 1; }

# --- Utility functions ---

# Classifies the HTTP status code into a human-readable category
classify_status() {
  local code="$1"
  if [[ "$code" == "000" || -z "$code" ]]; then
    echo "unreachable"
  elif (( code >= 200 && code < 300 )); then
    echo "ok"
  elif (( code >= 300 && code < 400 )); then
    echo "redirect"
  elif (( code >= 400 && code < 500 )); then
    echo "client_error"
  elif (( code >= 500 )); then
    echo "server_error"
  else
    echo "unknown"
  fi
}

# Returns a visual icon based on the status category
status_icon() {
  case "$1" in
    ok)           echo "✅" ;;
    redirect)     echo "↩️ " ;;
    client_error) echo "❌" ;;
    server_error) echo "🔥" ;;
    unreachable)  echo "🚫" ;;
    *)            echo "❓" ;;
  esac
}

# Returns the ANSI color code based on the status category
status_color() {
  case "$1" in
    ok)           echo "$GREEN" ;;
    redirect)     echo "$YELLOW" ;;
    client_error) echo "$RED" ;;
    server_error) echo "$RED" ;;
    unreachable)  echo "$RED" ;;
    *)            echo "$NC" ;;
  esac
}

# Checks a single link and writes the result to a temp JSON file
check_link() {
  local file_name="$1"
  local url="$2"
  local tmp_file="$3"
  local lock_file="$4"  # Isolated lock file inside TMP_DIR to avoid conflicts between parallel runs

  local http_code
  local curl_exit=0
  local error_msg=""
  local final_url=""
  local response_time=""

  # Measure response time in milliseconds
  # Note: date +%s%3N works on Linux (ubuntu-latest). On macOS it falls back to 0.
  local start_ts end_ts
  start_ts=$(date +%s%3N 2>/dev/null || echo 0)

  # Perform the HTTP request and capture the status code
  http_code=$(curl \
    --silent \
    --output /dev/null \
    --write-out "%{http_code}" \
    --location \
    --max-redirs 5 \
    --connect-timeout "$TIMEOUT" \
    --max-time "$((TIMEOUT * 2))" \
    --retry "$RETRIES" \
    --retry-delay 2 \
    --user-agent "Mozilla/5.0 (LinkChecker/1.0)" \
    "$url" 2>/dev/null) || curl_exit=$?

  end_ts=$(date +%s%3N 2>/dev/null || echo 0)
  response_time=$(( end_ts - start_ts ))

  # Capture the final URL after any redirects
  final_url=$(curl \
    --silent \
    --output /dev/null \
    --write-out "%{url_effective}" \
    --location \
    --max-redirs 5 \
    --connect-timeout "$TIMEOUT" \
    --max-time "$((TIMEOUT * 2))" \
    --user-agent "Mozilla/5.0 (LinkChecker/1.0)" \
    "$url" 2>/dev/null) || true

  # If curl failed or returned no code, mark as unreachable
  if [[ $curl_exit -ne 0 || -z "$http_code" ]]; then
    http_code="000"
    error_msg="Could not connect (curl exit: $curl_exit)"
  fi

  local status
  status=$(classify_status "$http_code")
  local icon
  icon=$(status_icon "$status")
  local color
  color=$(status_color "$status")

  # Escape special characters for valid JSON output
  local url_esc file_esc final_esc err_esc
  url_esc=$(printf '%s'   "$url"        | sed 's/\\/\\\\/g; s/"/\\"/g')
  file_esc=$(printf '%s'  "$file_name"  | sed 's/\\/\\\\/g; s/"/\\"/g')
  final_esc=$(printf '%s' "$final_url"  | sed 's/\\/\\\\/g; s/"/\\"/g')
  err_esc=$(printf '%s'   "$error_msg"  | sed 's/\\/\\\\/g; s/"/\\"/g')

  # Write the result as a JSON object to the temp file
  cat > "$tmp_file" <<EOF
{
    "file_name": "$file_esc",
    "link": "$url_esc",
    "http_code": $http_code,
    "status": "$status",
    "final_url": "$final_esc",
    "response_time_ms": $response_time,
    "error": "$err_esc"
  }
EOF

  # Print to console using flock to prevent garbled output from parallel processes
  {
    flock 200
    echo -e "${icon} ${color}[${http_code}]${NC} ${BOLD}${status}${NC} — ${CYAN}${url}${NC}  ${YELLOW}(${response_time}ms)${NC}"

    # Show the source file name only when there is an error
    if [[ -n "$error_msg" ]]; then
      # Network-level failure (unreachable)
      echo -e "   └─ ⚠️  $error_msg"
      echo -e "   ↳ ${BOLD}$file_name${NC}"
    elif [[ "$status" == "client_error" || "$status" == "server_error" ]]; then
      # HTTP 4xx or 5xx — show which file referenced this broken link
      echo -e "   ↳ ${BOLD}$file_name${NC}"
    elif [[ "$final_url" != "$url" && -n "$final_url" ]]; then
      # Show redirect destination if the URL changed
      echo -e "   └─ ↪  Redirected to: $final_url"
    fi
  } 200>"$lock_file"
}

# Export functions and variables so they are available in subshells (parallel jobs)
export -f check_link classify_status status_icon status_color
export TIMEOUT RETRIES RED GREEN YELLOW CYAN BOLD NC

# --- Parse input JSON — extract file_name and link arrays ---
# Simple parsing without jq: reads values from "file_name" and "link" fields
mapfile -t file_names < <(grep '"file_name"' "$INPUT_FILE" | sed 's/.*"file_name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/')
mapfile -t links      < <(grep '"link"'      "$INPUT_FILE" | sed 's/.*"link"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/')

total=${#links[@]}

# Exit early if no links were found in the input file
if [[ $total -eq 0 ]]; then
  echo -e "${YELLOW}⚠️  No links found in '$INPUT_FILE'.${NC}"
  echo "[]" > "$OUTPUT_FILE"
  exit 0
fi

echo -e "${BOLD}============================================${NC}"
echo -e "${BOLD}  🔗 Link Checker${NC}"
echo -e "${BOLD}============================================${NC}"
echo -e "  📂 Input    : $INPUT_FILE"
echo -e "  💾 Output   : $OUTPUT_FILE"
echo -e "  🔢 Total    : $total link(s)"
echo -e "  ⏱  Timeout  : ${TIMEOUT}s | 🔄 Retries: $RETRIES | ⚡ Parallel: $PARALLEL"
echo -e "${BOLD}--------------------------------------------${NC}"

# --- Temporary directory setup ---
TMP_DIR=$(mktemp -d)

# Lock file isolated inside TMP_DIR to prevent collisions when multiple
# workflow runs execute simultaneously on the same runner
LOCK_FILE="$TMP_DIR/check_links_lock"
touch "$LOCK_FILE"
export LOCK_FILE

# Clean up temp directory on exit (success or failure)
trap 'rm -rf "$TMP_DIR"' EXIT

# --- Run link checks in parallel using a manual semaphore ---
declare -a pids=()
declare -a tmp_files=()

for (( i=0; i<total; i++ )); do
  tmp_file="$TMP_DIR/result_${i}.json"
  tmp_files+=("$tmp_file")

  # Launch check in background, passing the isolated lock file
  check_link "${file_names[$i]:-unknown}" "${links[$i]}" "$tmp_file" "$LOCK_FILE" &
  pids+=($!)

  # Throttle parallelism: wait for the oldest job before launching a new one
  if (( ${#pids[@]} >= PARALLEL )); then
    wait "${pids[0]}"
    pids=("${pids[@]:1}")
  fi
done

# Wait for any remaining background jobs to finish
for pid in "${pids[@]}"; do
  wait "$pid"
done

# --- Assemble final JSON output from all temp result files ---
{
  echo "["
  last=$(( total - 1 ))
  for (( i=0; i<total; i++ )); do
    if [[ -f "${tmp_files[$i]}" ]]; then
      content=$(cat "${tmp_files[$i]}")
      if (( i < last )); then
        echo "  $content,"
      else
        echo "  $content"
      fi
    fi
  done
  echo "]"
} > "$OUTPUT_FILE"

# --- Statistical summary ---
# FIX: use $(( var + 1 )) instead of (( var++ )) to avoid exit code 1
# when the counter is 0, which would kill the script under set -e
ok_count=0; redir_count=0; err_count=0; unreach_count=0

for tmp_f in "${tmp_files[@]}"; do
  [[ -f "$tmp_f" ]] || continue
  s=$(grep '"status"' "$tmp_f" | sed 's/.*"status"[[:space:]]*:[[:space:]]*"\(.*\)".*/\1/')
  case "$s" in
    ok)                        ok_count=$(( ok_count + 1 ))           ;;
    redirect)                  redir_count=$(( redir_count + 1 ))     ;;
    client_error|server_error) err_count=$(( err_count + 1 ))         ;;
    unreachable)               unreach_count=$(( unreach_count + 1 )) ;;
  esac
done

echo -e "${BOLD}============================================${NC}"
echo -e "${BOLD}  📊 Summary${NC}"
echo -e "${BOLD}--------------------------------------------${NC}"
echo -e "  ${GREEN}✅ OK (2xx)        : $ok_count${NC}"
echo -e "  ${YELLOW}↩️  Redirect (3xx)  : $redir_count${NC}"
echo -e "  ${RED}❌ Error (4xx/5xx) : $err_count${NC}"
echo -e "  ${RED}🚫 Unreachable     : $unreach_count${NC}"
echo -e "  Total              : $total"
echo -e "${BOLD}============================================${NC}"
echo -e "📄 Results saved to: ${CYAN}$OUTPUT_FILE${NC}"

# --- Fail the workflow if any 4xx/5xx errors were found ---
# exit 1 causes GitHub Actions to mark the step and job as failed (red ❌)
if (( err_count > 0 )); then
  echo -e "${RED}❌ $err_count broken link(s) with 4xx/5xx errors were found.${NC}" >&2
  exit 1
fi